"""Golden vectors for the Decimal subset used by grading, generated by CPython's decimal module."""
import json, random, sys
from decimal import Decimal, getcontext, DivisionByZero, InvalidOperation, Overflow, DivisionUndefined
ctx = getcontext(); assert ctx.prec == 28 and ctx.rounding == "ROUND_HALF_EVEN" and ctx.Emax == 999999

rng = random.Random(4242)
def lit():
    k = rng.random()
    if k < .25: return str(rng.randint(-20, 20))
    if k < .5: return f"{rng.randint(-99999, 99999)}.{rng.randint(0, 99999):05d}"[: rng.randint(2, 11)]
    if k < .6: return f"{rng.choice(['','+','-'])}{rng.randint(0, 9)}e{rng.randint(-40, 40)}"
    if k < .7: return rng.choice(["0", "0.0", "0.00", "-0", "-0.0", "0e5", "0E-7", ".5", "5.", "1_000", " 3 "])
    if k < .8: return "".join(rng.choice("0123456789") for _ in range(rng.randint(20, 40))) + ("." + "".join(rng.choice("0123456789") for _ in range(rng.randint(0, 20))) if rng.random() < .6 else "")
    if k < .9: return rng.choice(["1e999990", "1e-999990", "1e999999", "1e1000000", "9"*30 + "e999990", "1e-1000020"])
    return rng.choice(["0.1", "0.2", "0.3", "1", "3", "7", "1.1", "2.50", "100", "0.01", "33.333333333333333333333333333", "1e3", "1E+3"])

def run(f):
    try: v = f(); return {"v": str(v) if isinstance(v, Decimal) else v}
    except (Overflow,): return {"err": "overflow"}
    except DivisionByZero: return {"err": "division_by_zero"}
    except DivisionUndefined: return {"err": "division_undefined"}
    except InvalidOperation: return {"err": "invalid"}

out = {"parse": [], "binary": [], "unary": [], "quantize": []}
for t in ["1", "-1", "+1", "1.", ".5", "1e5", "1E+5", "1e-5", "  7  ", "1_0", "", "e5", ".", "-", "1e", "1.2.3", "0x10", "١٢", "nan", "inf", "Infinity", "1 2", "00012", "-0.000", "0e-1000", "1e999999999999"]:
    try: d = Decimal(t); out["parse"].append({"in": t, "str": str(d), "tuple": [d.as_tuple().sign, str(d.as_tuple().exponent)], "special": not d.is_finite()})
    except Exception: out["parse"].append({"in": t, "error": True})
for _ in range(2500):
    a, b = lit(), lit()
    try: A, B = Decimal(a), Decimal(b)
    except Exception: continue
    row = {"a": a, "b": b}
    row["add"] = run(lambda: A + B); row["sub"] = run(lambda: A - B); row["mul"] = run(lambda: A * B); row["div"] = run(lambda: A / B)
    row["cmp"] = (A > B) - (A < B); row["max"] = str(max(A, B)); row["min"] = str(min(A, B))
    row["abs"] = run(lambda: abs(A)); row["bool"] = bool(A)
    out["binary"].append(row)
for _ in range(400):
    a = lit()
    try: A = Decimal(a)
    except Exception: continue
    n = rng.randint(1, 7); d = rng.randint(1, 9)
    out["unary"].append({"a": a, "div_int": run(lambda: A / Decimal(n)), "n": n, "mul_int": run(lambda: A * Decimal(d)), "d": d})
    out["quantize"].append({"a": a, "q4": run(lambda: A.quantize(Decimal("0.0001")))})
print(json.dumps(out, indent=0))
